const baseUrl = String($env.WEBHOOK_URL || '').replace(/\/$/, '');
const summary = { telegram: [], discord: null, mongodb: null, white_label_brand: $env.BRAND_NAME || 'Tradesejon' };

for (const [label, tok, path] of [
  ['CEO_BOT', $env.TELEGRAM_CEO_BOT_TOKEN, 'tradesejon-ceo'],
  ['PR_BOT', $env.TELEGRAM_PR_BOT_TOKEN, 'tradesejon-pr'],
  ['TRADER_BOT', $env.TELEGRAM_TRADER_BOT_TOKEN, 'tradesejon-trader']
]) {
  if (!tok || !baseUrl) { summary.telegram.push({ bot: label, ok: false, error: 'Missing token or WEBHOOK_URL' }); continue; }
  try {
    const res = await fetch(`https://api.telegram.org/bot${tok}/setWebhook?url=${encodeURIComponent(baseUrl + '/webhook/' + path)}`).then(r => r.json());
    summary.telegram.push({ bot: label, ok: res.ok, description: res.description });
  } catch (e) { summary.telegram.push({ bot: label, ok: false, error: e.message }); }
}

if ($env.DISCORD_BOT_TOKEN) {
  try {
    const dc = await fetch('https://discord.com/api/v10/users/@me', { headers: { 'Authorization': `Bot ${$env.DISCORD_BOT_TOKEN}` } }).then(r => r.json());
    summary.discord = { ok: Boolean(dc.id), bot_username: dc.username || null };
  } catch (e) { summary.discord = { ok: false, error: e.message }; }
}

if ($env.MONGODB_URI) {
  try {
    const { MongoClient } = require('mongodb');
    const c = new MongoClient($env.MONGODB_URI);
    await c.connect();
    const db = c.db($env.MONGODB_DB || 'tradesejon_prod');
    await db.collection('leads').createIndex({ email: 1 }, { unique: true, sparse: true });
    await db.collection('members').createIndex({ discord_user_id: 1 }, { unique: true, sparse: true });
    await db.collection('audit_logs').createIndex({ timestamp: -1 });
    await c.close();
    summary.mongodb = { ok: true, indexes_created: true };
  } catch (e) { summary.mongodb = { ok: false, error: e.message }; }
}

return [{ json: { ok: true, provisioning: summary, timestamp: new Date().toISOString() } }];
